#!/usr/bin/env python3
"""Evidence-linked whole-guest instruction attribution; no native timing claim."""
import json,subprocess
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
P=Path(__file__).resolve().parent;A=json.loads((P/'analysis-profile-002.json').read_text());assert A['status']=='pass';R=A['rows'];V=json.loads((P/'replay-profile-002.json').read_text());assert V['checks']==6 and V['status']=='pass'
D=P/'profile-002';H=json.loads((D/'host.json').read_text());I=json.loads((P/'profile-input.json').read_text());tag='[pcc:unverified]'
labels=['Product A1','Packed B1','Packed B2','Product A2','rho plain','rho negation']
fig,ax=plt.subplots(figsize=(9,3.4));bars=ax.bar(range(6),[r['ir']/1e6 for r in R],color=['#4b7488','#bc9857','#bc9857','#4b7488','#9baba7','#6f8580'])
for b,r in zip(bars,R):ax.text(b.get_x()+b.get_width()/2,b.get_height()+2,f"{r['ir']/1e6:.6f}",ha='center',fontsize=8)
ax.set_xticks(range(6),labels);ax.set_ylabel('Whole-guest instruction reads (million Ir)');ax.set_ylim(0,170);ax.grid(axis='y',alpha=.2);ax.set_title('Fixed N27 development target 0; every capture retained');fig.tight_layout()
for e in ['png','svg']:fig.savefig(P/f'profile002-totals.{e}',dpi=180)
plt.close(fig)
f=R[0]['functions'][:10]
names=['Field inverse','Table flush / insertion','Table builder body','Vector pair helper','Scalar point addition','Collector body','Seen-target insertion','Vector output extension','Pair-table probe','Matrix row insertion']
assert all(t in x['function'] for t,x in zip(['inv_clmul','closure#3','build_binary_batch','add_cached_narrow','FastCurve>::add','collect_and_solve_with','HashMap','spec_extend','PairTable>::probe','IncrementalGauss'],f))
fig,ax=plt.subplots(figsize=(9,4.6));ax.barh(range(10),[x['fraction']*100 for x in f],color='#4f807c');ax.set_yticks(range(10),names);ax.invert_yaxis();ax.set_xlabel('Exclusive fraction of whole-guest Ir (%)');ax.set_title('Product A1: exclusive costs; no overlapping call costs added');ax.grid(axis='x',alpha=.2)
for i,x in enumerate(f):ax.text(x['fraction']*100+.3,i,f"{x['fraction']*100:.2f}%",va='center',fontsize=8)
ax.set_xlim(0,34);fig.tight_layout()
for e in ['png','svg']:fig.savefig(P/f'profile002-exclusive.{e}',dpi=180)
plt.close(fig)
(P/'profile002-flow.dot').write_text('''digraph G {rankdir=LR;node[shape=box,style="rounded,filled",fillcolor="#e6eeee",fontname="Helvetica"];a[label="Point additions\\n56,958 inverse calls"];b[label="Point doubles\\n2,073 calls"];c[label="Base point construction\\n1,023 calls"];d[label="Batch inversion\\n1 call"];e[label="Gf2::inv\\n60,055 calls"];f[label="inv_clmul\\n43,239,600 exclusive Ir"];a->e;b->e;c->e;d->e;e->f;}''')
for e in ['png','svg']:subprocess.run(['dot','-T'+e,str(P/'profile002-flow.dot'),'-o',str(P/f'profile002-flow.{e}')],check=True)
for p in P.glob('profile002-*.svg'):p.write_text('\n'.join(l.rstrip() for l in p.read_text().splitlines())+'\n')
intro=f'{tag} Completed job 20261116-114826-d911 produces six whole-guest Callgrind captures after the actual ordinary-PCLMUL/packed preflight passes 25 complete witness maps. Existing independent Python arithmetic replays all six scalar answers. Raw totals, exclusive instruction sums and tool annotation totals agree. Claim 0e7008 is unsigned producer/tool evidence.'
count=f'{tag} Product Ir repeats are {A["product_ir"]}; packed repeats are {A["packed_ir"]}. Median product/packed guest-Ir ratio is {A["supplementary_product_over_packed_ir_ratio"]:.9f}. The difference is about 0.28% of whole-process instruction reads, consistent in scope with a small component change; it is not a native wall ratio. Repeat relative ranges: product {A["repeated_ir_relative_ranges"]["product"]:.9g}, packed {A["repeated_ir_relative_ranges"]["packed"]:.9g}. Two repeats do not support a confidence interval.'
boundary=f'{tag} Ir covers guest runtime loader/startup, inputs/units, context/base/cache/table, every query/matrix/check, output and cleanup. Valgrind interprets the CPU code. These are instruction-read events, not hardware retirement, cycles, latency or the primary single-target online interval. Instrumented clocks are retained only as execution/resource receipts. Rho rows use the same complete guest-process boundary on the identical point; their instruction gap is supplementary.'
table=[['Capture','Whole-guest Ir','Ir / rho negation']]
for label,r in zip(labels,R):table.append([label,f"{r['ir']:,}",f"{r['ir']/R[-1]['ir']:.6f}"])
attribution=f'{tag} In Product A1, field inversion accounts for 43,239,600 exclusive Ir (29.15%). Table builder body plus flush account for 37,835,845 Ir (25.51%); the vector pair helper accounts for 15,615,021 Ir (10.53%). The call graph records 60,055 field inversions: 56,958 from scalar additions, 2,073 from doubling, 1,023 from factor-base point construction and 1 from batch inversion. Call-edge costs overlap their callees and are not added to exclusive fractions.'
work=f'{tag} Both IC modes execute 55,922 trials, 55,866 oracle lookups, 256 relations/rank and 55,865 walk steps, with 56 repeated targets skipped. Actual vector pairs are 280,368 per IC capture; only packed arms report the same positive packed-square count. Existing oracle counter inversions=0 is scoped to the oracle, not all group arithmetic; it does not contradict the field-inverse call graph. Deterministic work signatures match across all four IC captures.'
resources=f'{tag} Requested one L4, 4 CPU, 8 GiB, 900s; CPU work only and one allowed CPU pinned. Controller 780s, IC child 120s, rho 60s, preflight 90s and exports 20s. Instrumentation virtual-address cap 32 GiB is distinct from requested physical 8 GiB. Valgrind 3.22.0, package 1:3.22.0-0ubuntu3, tool-file hashes, lscpu, cgroups, process CPU/wall/RSS/fault receipts and raw captures are retained. Physical memory technology/speed/channels, placement, throttle/OOM coverage and host isolation remain unqualified; record invalid for promotion.'
source=f'{tag} Exact registered curve EC1N27Crbh9ce93808c7a5, prefix dimension 10, 531 sign columns; one development point 0, workload 1d41eea76cd6. Binary {I["prepared"]["binary_sha256"]}, source {I["prepared"]["source_commit"]}, preparation {I["prepared"]["source_job"]}; calibration from timing {I["timing_job"]} index 4, SHA-pinned with source-job metadata. Original inverse/matrix and all scalar guards remain. Rust inlining and missing source-line information limit attribution granularity; full symbols, instructions and call edges remain available.'
nextstep='Proposed next step: batch the independent additions used to generate relation queries for this one target, using the existing simultaneous-inversion kernel. The current walk chooses each next jump from its current point, so batching changes the collector schedule/query law and requires a fresh candidate and frozen comparison. Preserve global duplicate/identity guards, coefficient tracking, lazy restarts, every setup and unused buffered operation, trial caps, ordinary relation yield, matrix counts and scalar replay. It is a known batching method, with its binary IC adaptation and performance still unmeasured; no cross-target amortization or novelty claim.'
history='The initial profile001 stops before arithmetic because the annotator version command prints 3.22.0 but returns 255. All 11 outputs, failed record and one-page report remain. The published version-only amendment records package version/tool hashes and uses a distinct output path. No ISA, arithmetic, resource or control gate is relaxed. No host capability filter is used.'
erratum=f'{tag} Timing-boundary correction20c68d: earlier cold labels based on context_ns plus RunReport.wall_seconds omit some scope-exit cleanup. Their raw values remain a narrower computation window; complete cold and primary online costs were not established. The whole-guest Ir in this report includes teardown and is unaffected. See COST_WINDOW_ERRATUM.md and problems/ic-probe-teardown-window.md before new timing.'
sources='Sources checked: PROTOCOL.md; official Callgrind manual and platform list; research-kb sources c5b44937741b2f73ed2237dced16f1c1 and c525825f5c51c500234cb8b8749a45dc, owning field/table/collector code and the lead atlas. The batched-inversion lead is closed_known; prime-IC engineering records also contain negative wide-batching results. The historical matched-rho note has a partial withdrawal for arithmetic mismatch and multiple-target scope; none of its ratios are transferred here. No curve, isogeny or endomorphism fact changes, so the curve/route graph set is unaffected. See NEXT_LEAD.md for exact source pointers and obligations.'
md=['# Native IC instruction attribution: fixed N27 development point','',intro,'',count,'',boundary,'','| Capture | Whole-guest Ir | Ir / matched rho negation |','|---|---:|---:|',*['| '+' | '.join(x)+' |' for x in table[1:]],'','![All captures](profile002-totals.svg)','',attribution,'',work,'','![Exclusive attribution](profile002-exclusive.svg)','','![Inverse callers](profile002-flow.svg)','',resources,'',source,'',nextstep,'',history,'',erratum,'',sources,'','Evidence: all 78 raw outputs, six .callgrind captures, exclusive/inclusive exports, disassembly, analysis-profile-002.json, replay-profile-002.json and the lossless SHA/URI bundle.']
(P/'REPORT-profile002.md').write_text('\n'.join(md)+'\n')
styles=getSampleStyleSheet();styles['BodyText'].fontSize=9.3;styles['BodyText'].leading=12
para=lambda s:Paragraph(s.replace('&','&amp;').replace('<','&lt;'),styles['BodyText'])
def tab(data,widths):
 t=Table(data,colWidths=widths);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e0eded')),('GRID',(0,0),(-1,-1),.3,colors.grey),('FONTSIZE',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),6)]));return t
story=[Paragraph('Native IC instruction attribution',styles['Title']),para('Fixed N27 development point 0 — whole-guest Ir, not native time'),Spacer(1,10),para(intro),Spacer(1,10),tab(table,[130,150,180]),Spacer(1,10),para(count),Spacer(1,10),Image(str(P/'profile002-totals.png'),width=493,height=186),Spacer(1,10),para(boundary),PageBreak(),Paragraph('Where the instruction work goes',styles['Title']),para(attribution),Spacer(1,8),Image(str(P/'profile002-exclusive.png'),width=493,height=252),Spacer(1,8),para(work),Spacer(1,8),Image(str(P/'profile002-flow.png'),width=493,height=125,kind='proportional'),PageBreak(),Paragraph('Scope, controls and next experiment',styles['Title'])]
for text in [resources,source,nextstep,history,erratum,sources]:story += [para(text),Spacer(1,11)]
SimpleDocTemplate(str(P/'REPORT-profile002.pdf'),leftMargin=42,rightMargin=42,topMargin=36,bottomMargin=36).build(story)
